// Builds the facts and the prompt. Over the sea Nominatim finds nothing, so the ocean is named from rough coordinate boxes.
const req = $('Besucher-Knopf (Webhook)').first().json.body || {};
const lang = ['de', 'en', 'it'].includes(req.lang) ? req.lang : 'en';
const iss = $('Wo ist die ISS?').first().json;
let geo = null; try { geo = $('Was liegt darunter?').first().json; } catch (e) {}
const lat = iss.latitude, lon = iss.longitude;
const OCEAN = {
  de: { arc: 'Nordpolarmeer', sou: 'Südlicher Ozean', atl: 'Atlantik', ind: 'Indischer Ozean', pac: 'Pazifik' },
  en: { arc: 'Arctic Ocean', sou: 'Southern Ocean', atl: 'Atlantic Ocean', ind: 'Indian Ocean', pac: 'Pacific Ocean' },
  it: { arc: 'Mar Glaciale Artico', sou: 'Oceano Australe', atl: 'Oceano Atlantico', ind: 'Oceano Indiano', pac: 'Oceano Pacifico' } }[lang];
const ocean = lat > 66 ? OCEAN.arc : lat < -55 ? OCEAN.sou
  : (lat >= 0 ? (lon > -82 && lon < -5) : (lon > -68 && lon < 20)) ? OCEAN.atl
  : (lon >= 20 && lon < 120 && lat < 25) ? OCEAN.ind : OCEAN.pac;
const a = geo && !geo.error && geo.address ? geo.address : null;
const land = a ? [a.state || a.region || a.county || '', a.country || ''].filter(Boolean).join(', ') : '';
const place = land || ocean;
// local solar time under the ISS: UTC + longitude / 15 hours
const solar = new Date(Date.now() + lon / 15 * 3600000);
const local = solar.toISOString().slice(11, 16);
const facts = { place, over_land: !!land, altitude_km: Math.round(iss.altitude), speed_kmh: Math.round(iss.velocity),
                local_time_below: local, iss_in_sunlight: iss.visibility === 'daylight' };
const LANG = { de: 'German, informal "du"', en: 'English', it: 'Italian, informal "tu"' }[lang];
const prompt = 'You are an astronaut on the International Space Station writing a short, funny postcard to a curious stranger on Earth. '
  + `Write in ${LANG}. Facts: ${JSON.stringify(facts)}. `
  + 'Rules: a greeting of max 6 words, then 2-4 sentences (max 330 characters) mentioning the place below and 1-2 of the numbers exactly as given; '
  + 'only general, well-known facts about the place; if the place is linked to war, disaster or tragedy, stay neutral and kind, no jokes about it; '
  + 'no hashtags, no emojis. Answer with JSON only: {"greeting":"","text":""}';
return [{ json: { id: req.id, lang, lat, lon, alt: iss.altitude, vel: iss.velocity, day: iss.visibility === 'daylight',
  place, cc: a && a.country_code ? a.country_code : '', local,
  body: { model: 'openai/gpt-oss-120b', temperature: 0.8, max_tokens: 1200, response_format: { type: 'json_object' },
          messages: [{ role: 'user', content: prompt }] } } }];

// Reads the AI answer; if it fails, a template card is used so the visitor always gets a postcard.
const d = $('Postkarte schreiben').first().json;
let c = null;
try { const m = String($input.first().json.choices[0].message.content).match(/\{[\s\S]*\}/); c = JSON.parse(m[0]); } catch (e) {}
if (!c || !c.greeting || !c.text) {
  const T = { de: [`Grüße aus ${Math.round(d.alt)} km Höhe!`, `Gerade fliege ich mit ${Math.round(d.vel)} km/h über ${d.place}. Unten ist es ${d.local} Uhr. Schöne Grüße von der ISS!`],
              en: [`Greetings from ${Math.round(d.alt)} km up!`, `Right now I am flying over ${d.place} at ${Math.round(d.vel)} km/h. Down there it is ${d.local}. Best wishes from the ISS!`],
              it: [`Saluti da ${Math.round(d.alt)} km di quota!`, `In questo momento sorvolo ${d.place} a ${Math.round(d.vel)} km/h. Laggiù sono le ${d.local}. Un saluto dalla ISS!`] }[d.lang];
  c = { greeting: T[0], text: T[1] };
}
const { body, ...card } = d;
return [{ json: { ...card, greeting: String(c.greeting).slice(0, 90), text: String(c.text).slice(0, 700) } }];
